FORK_ALLOWLIST = {"Trabalho-Sofware-Basico"}


def list_profile_repos():
    """Endpoint publico users/{login}/repos: funciona com qualquer token,
    ja retorna so o que e publico. Forks ficam de fora (nao e codigo meu),
    exceto os listados em FORK_ALLOWLIST."""
    result = subprocess.run(
        ["gh", "api", f"users/{PROFILE_OWNER}/repos?per_page=100&type=owner", "--paginate", "-q", ".[]"],
        capture_output=True, text=True, check=True,
    )
    repos = [json.loads(line) for line in result.stdout.splitlines() if line.strip()]
    return [
        r for r in repos
        if r["name"] != PROFILE_REPO_NAME and (not r["fork"] or r["name"] in FORK_ALLOWLIST)
    ]


def count_lines(repo_full_name):
    """Clona sem autenticacao: sao sempre repositorios publicos."""
    tmp = tempfile.mkdtemp(prefix="stat-")
    url = f"https://github.com/{repo_full_name}.git"
    counts = {}
    try:
        subprocess.run(
            ["git", "clone", "--depth", "1", "--quiet", url, tmp],
            check=True, capture_output=True, text=True, timeout=120,
        )
        for root, dirs, files in os.walk(tmp):
            dirs[:] = [d for d in dirs if d not in IGNORE_DIRS and not d.startswith(".")]
            for fname in files:
                lang = EXT_LANG.get(os.path.splitext(fname)[1].lower())
                if not lang:
                    continue
                try:
                    with open(os.path.join(root, fname), "rb") as fh:
                        n = sum(1 for line in fh if line.strip())
                except OSError:
                    continue
                counts[lang] = counts.get(lang, 0) + n
    except subprocess.CalledProcessError as e:
        print(f"  [aviso] falha ao clonar {repo_full_name}: {e.stderr.strip()[:200]}", file=sys.stderr)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    return counts


def count_commits(repo_full_name):
    """Numero total de commits do branch padrao: pede so 1 commit por pagina
    e le o numero da ultima pagina no header Link (rel="last")."""
    result = subprocess.run(
        ["gh", "api", f"repos/{repo_full_name}/commits?per_page=1", "-i"],
        capture_output=True, text=True,
    )
    if result.returncode != 0:
        return 0
    headers, _, body = result.stdout.partition("\r\n\r\n")
    if not body:
        headers, _, body = result.stdout.partition("\n\n")
    m = re.search(r'page=(\d+)>;\s*rel="last"', headers)
    if m:
        return int(m.group(1))
    try:
        arr = json.loads(body)
        return len(arr) if isinstance(arr, list) else 0
    except json.JSONDecodeError:
        return 0


def orion_index_last_update():
    """Data do ultimo commit que mexeu no card combinado do Orion Index.
    Via API, nao `git log` local: o checkout deste workflow e raso
    (fetch-depth 1), entao um `git log -- path` local devolve a data do
    unico commit baixado mesmo quando ele nao tocou o arquivo."""
    result = subprocess.run(
        ["gh", "api", "repos/GustavoVieiraDeAraujo/Orion-Index/commits?path=docs/orion-index.svg&per_page=1",
         "-q", ".[0].commit.committer.date"],
        capture_output=True, text=True,
    )
    if result.returncode != 0 or not result.stdout.strip():
        return None
    try:
        dt = datetime.datetime.fromisoformat(result.stdout.strip().replace("Z", "+00:00"))
    except ValueError:
        return None
    return dt.strftime("%d/%m/%Y")


def short_label(text, max_chars=15):
    return text if len(text) <= max_chars else text[: max_chars - 1] + "…"


def render_bar_card(data, title, svg_path, unit="pct", color_map=None,
                     default_color="#60a5fa", top_n=5, order="value", grad_id="cardBg",
                     layout="side", label_w=84, label_chars=13):
    """Cartao de barras top N. `layout="side"`: rotulo a esquerda, barra a
    direita (rotulo curto). `layout="stacked"`: rotulo em cima, barra
    full-width embaixo (rotulo longo, tipo nome de repositorio)."""
    color_map = color_map or {}
    items = list(data.items())
    if order == "value":
        items = sorted(items, key=lambda kv: kv[1], reverse=True)
    items = items[:top_n]
    grand_total = sum(data.values()) or 1
    bar_scale = max((v for _, v in items), default=1)

    card_pad = 20
    title_h = 30
    width = CARD_NATIVE_W
    row_h = 50 if layout == "stacked" else 32
    bar_x = card_pad + label_w + 10
    bar_max_w = width - bar_x - card_pad - 56
    stacked_bar_w = width - card_pad * 2 - 54
    height = card_pad * 2 + title_h + row_h * len(items)

    rows = []
    for i, (key, n) in enumerate(items):
        color = color_map.get(key, default_color)
        if unit == "pct":
            val_label = f"{100 * n / grand_total:.1f}%"
        elif unit == "loc":
            val_label = f"{n:,}".replace(",", ".")
        else:
            val_label = f"{n}"
        label = short_label(str(key), label_chars)

        if layout == "stacked":
            row_top = card_pad + title_h + i * row_h
            bar_w = max(3, round(stacked_bar_w * n / bar_scale))
            rows.append(f'''
    <text x="{card_pad}" y="{row_top + 15}" class="lbl">{label}</text>
    <rect x="{card_pad}" y="{row_top + 23}" width="{stacked_bar_w}" height="11" rx="5.5" class="track"/>
    <rect x="{card_pad}" y="{row_top + 23}" width="{bar_w}" height="11" rx="5.5" fill="{color}" class="bar"/>
    <text x="{card_pad + stacked_bar_w + 8}" y="{row_top + 32}" class="val">{val_label}</text>''')
        else:
            bar_w = max(3, round(bar_max_w * n / bar_scale))
            cy = card_pad + title_h + i * row_h + row_h / 2
            rows.append(f'''
    <text x="{card_pad + label_w}" y="{cy + 4}" text-anchor="end" class="lbl">{label}</text>
    <rect x="{bar_x}" y="{cy - 6.5}" width="{bar_max_w}" height="13" rx="6.5" class="track"/>
    <rect x="{bar_x}" y="{cy - 6.5}" width="{bar_w}" height="13" rx="6.5" fill="{color}" class="bar"/>
    <text x="{bar_x + bar_max_w + 10}" y="{cy + 4}" class="val">{val_label}</text>''')

    card_particles = _particle_network_content(
        width, height, CARD_PARTICLE_COUNT, CARD_PARTICLE_SEED,
        CARD_PARTICLE_LINK_DIST, CARD_PARTICLE_COLOR, CARD_PARTICLE_MOVE_RANGE, CARD_PARTICLE_DUR_RANGE,
        radius_range=(1, 2), opacity_scale=CARD_PARTICLE_OPACITY, pulse=False,
    )

    svg = f'''<svg width="{width}" height="{height}" viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{title}">
  <defs>
    <linearGradient id="{grad_id}" x1="0%" y1="0%" x2="100%" y2="0%">
      <stop offset="0%" stop-color="{CARD_BG_FROM}"/>
      <stop offset="100%" stop-color="{CARD_BG_TO}"/>
    </linearGradient>
    <clipPath id="cardClip{grad_id}">
      <rect x="0" y="0" width="{width}" height="{height}" rx="14"/>
    </clipPath>
  </defs>
  <style>
    text {{ font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif; font-size: 13.5px; }}
    .card {{ fill: url(#{grad_id}); stroke: {CARD_STROKE}; stroke-width: 1; }}
    .title {{ fill: {CARD_TITLE_COLOR}; font-weight: 700; font-size: 15.5px; }}
    .lbl {{ fill: {CARD_LABEL_COLOR}; font-weight: 600; }}
    .val {{ fill: {CARD_VALUE_COLOR}; }}
    .track {{ fill: {CARD_TRACK_COLOR}; }}
    .bar {{ stroke: rgba(255,255,255,0.2); stroke-width: 0.75; }}
  </style>
  <rect x="0" y="0" width="{width}" height="{height}" rx="14" class="card"/>
  <g clip-path="url(#cardClip{grad_id})">{card_particles}</g>
  <text x="{card_pad}" y="{card_pad + 17}" class="title">{title}</text>
  {"".join(rows)}
</svg>'''

    os.makedirs(os.path.dirname(svg_path), exist_ok=True)
    with open(svg_path, "w", encoding="utf-8") as f:
        f.write(svg)


def build_combined_row(panel_paths, out_path, cols=2):
    """Junta os cartoes numa grade (2 colunas por padrao). Concatena texto
    em vez de xml.etree pra nao esbarrar em conflito de id/namespace."""
    parsed = []
    for path in panel_paths:
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()
        w = float(re.search(r'width="([\d.]+)"', content).group(1))
        h = float(re.search(r'height="([\d.]+)"', content).group(1))
        body = re.search(r"<svg[^>]*>(.*)</svg>", content, re.DOTALL).group(1)
        parsed.append((body, w, h))

    col_w = parsed[0][1]
    row_h = max(h for _, _, h in parsed)
    n_rows = -(-len(parsed) // cols)  # ceil sem importar math
    total_w = cols * col_w + (cols - 1) * CARD_GAP
    total_h = n_rows * row_h + (n_rows - 1) * CARD_GAP

    groups = []
    for i, (body, w, h) in enumerate(parsed):
        col, row = i % cols, i // cols
        x, y = col * (col_w + CARD_GAP), row * (row_h + CARD_GAP)
        groups.append(f'<g transform="translate({x},{y})">{body}</g>')

    combined = (
        f'<svg width="{total_w}" height="{total_h}" viewBox="0 0 {total_w} {total_h}" '
        f'xmlns="http://www.w3.org/2000/svg">\n' + "\n".join(groups) + "\n</svg>\n"
    )

    with open(out_path, "w", encoding="utf-8") as f:
        f.write(combined)


# Parametros do banner, todos num lugar so pra ajustar e regenerar sem
# precisar entender a matematica por baixo. O que importa de verdade e o
# Banner/divisor no tema escuro, pra bater com os cartoes de estatistica
# (CARD_BG_* acima). Nada disso depende de servico externo -- os pontos e
# conexoes sao calculados aqui mesmo, com posicao pseudo-aleatoria fixa
# (mesma seed sempre), animando via SMIL (roda normalmente dentro de <img>
# no GitHub, confirmado ao vivo). Ajuste as constantes e regenere pra ver
# o resultado na hora.
BANNER_WIDTH = 854
BANNER_HEIGHT = 180
BANNER_BG = "#12161c"
BANNER_FONT_COLOR = "f0f6fc"
BANNER_PARTICLE_COUNT = 54        # grade com jitter (nao sorteio puro) -- cobre a faixa toda de forma uniforme, sem aglomerar
BANNER_PARTICLE_SEED = 11         # fixa o layout dos pontos (troca a "cara" da rede sem ser aleatorio a cada execucao)
BANNER_PARTICLE_LINK_DIST = 115   # distancia maxima (px) pra dois pontos ficarem ligados por uma linha
BANNER_PARTICLE_COLOR = "#8b949e"
BANNER_PARTICLE_MOVE_RANGE = (24, 18)  # deslocamento maximo em x, y (px) durante a animacao
BANNER_PARTICLE_DUR_RANGE = (5, 11)    # duracao minima/maxima (s) do movimento de cada ponto

# Versao discreta pras tabelas: menos pontos que o banner e sem pulsar de
# tamanho, opacidade baixa pra nao atrapalhar a leitura das barras/texto.
CARD_PARTICLE_COUNT = 20
CARD_PARTICLE_SEED = 4
CARD_PARTICLE_LINK_DIST = 80
CARD_PARTICLE_COLOR = "#8b949e"
CARD_PARTICLE_MOVE_RANGE = (10, 8)
CARD_PARTICLE_DUR_RANGE = (6, 12)
CARD_PARTICLE_OPACITY = 0.4


def _js_num(value):
    """Formata numero do jeito que o JS faria ao interpolar em template string
    (854/4 -> '213.5', mas 854/2 -> '427', nunca '427.0')."""
    if isinstance(value, float):
        value = round(value, 2)
        if value.is_integer():
            return str(int(value))
    return str(value)


def _grid_points(width, height, count, seed, pad=15, jitter=0.4, exclude_box=None, oversample=2.2):
    """Distribui `count` pontos numa grade com leve variacao aleatoria --
    mais uniforme pelo espaco todo do que sorteio puramente aleatorio, que
    tende a formar aglomerados e deixar cantos vazios (era o que
    acontecia antes, com rnd.uniform puro). Com exclude_box=(x0,y0,x1,y1)
    pula qualquer ponto que caia dentro dessa area (usado pra desviar do
    texto do nome no banner); pra compensar as celulas puladas e ainda
    preencher bem o espaco livre, gera a grade um pouco mais densa
    (oversample) e so corta pra `count` no final."""
    rnd = random.Random(seed)
    target = round(count * oversample) if exclude_box else count
    cols = max(1, round(math.sqrt(target * width / height)))
    rows = max(1, math.ceil(target / cols))
    if exclude_box:
        # banner bem largo (854x180) da poucas linhas nesse calculo por
        # aspecto (tipo 4-5) -- ai a faixa de cima/baixo do texto excluido
        # (~50px de altura) sobra com so 1 linha, enquanto as colunas dos
        # lados (que atravessam a altura toda) mantem todas as linhas, e
        # os pontos acabam concentrados nas pontas. Forcar mais linhas da
        # grade espalha melhor pelo espaco livre acima/abaixo tambem.
        rows = max(rows, 13)
        cols = max(1, math.ceil(target / rows))
    cell_w = (width - 2 * pad) / cols
    cell_h = (height - 2 * pad) / rows
    pts = []
    for r in range(rows):
        for c in range(cols):
            cx = pad + cell_w * (c + 0.5) + rnd.uniform(-cell_w * jitter, cell_w * jitter)
            cy = pad + cell_h * (r + 0.5) + rnd.uniform(-cell_h * jitter, cell_h * jitter)
            if exclude_box and exclude_box[0] <= cx <= exclude_box[2] and exclude_box[1] <= cy <= exclude_box[3]:
                continue
            pts.append((cx, cy))
    if len(pts) > count:
        # amostragem em passo fixo (nao embaralha e corta) -- os pontos ja
        # estao em ordem de varredura da grade, entao pular de `step` em
        # `step` mantem a cobertura espalhada por toda a area; embaralhar
        # e cortar podia por azar esvaziar uma faixa inteira (ex: o topo
        # ou a base do banner, perto do texto excluido)
        step = len(pts) / count
        pts = [pts[min(round(i * step), len(pts) - 1)] for i in range(count)]
    return pts, rnd


def _particle_network_content(width, height, count, seed, link_dist, color,
                               move_range, dur_range, radius_range=(1.8, 4),
                               opacity_scale=1.0, pulse=True, exclude_box=None):
    """Rede de pontos conectados por linhas, todos flutuando devagar --
    cada linha segue os MESMOS quadros de movimento dos dois pontos que
    ela liga (senao ela fica parada enquanto os pontos se afastam,
    parecendo elastico furado). Generico o bastante pra usar tanto no
    banner (mais pontos, mais visivel) quanto dentro dos cartoes de
    estatistica (poucos pontos, bem discreto, opacity_scale baixo).
    exclude_box=(x0,y0,x1,y1) desvia os pontos dessa area (o texto do
    nome, no caso do banner) -- lig linhas so conectam pontos que ja
    estao fora da area, entao tambem nao cruzam por cima do texto."""
    grid, rnd = _grid_points(width, height, count, seed, exclude_box=exclude_box)
    pts = []
    for x, y in grid:
        pts.append({
            "x": x, "y": y,
            "dx": rnd.uniform(-move_range[0], move_range[0]),
            "dy": rnd.uniform(-move_range[1], move_range[1]),
            "dur": rnd.uniform(*dur_range),
            "r": rnd.uniform(*radius_range),
        })

    lines = []
    for i in range(len(pts)):
        for j in range(i + 1, len(pts)):
            a, b = pts[i], pts[j]
            dist = math.hypot(a["x"] - b["x"], a["y"] - b["y"])
            if dist < link_dist:
                lines.append((a, b, dist))

    parts = []
    for a, b, dist in lines:
        opacity = max(0.06, 0.35 - dist / 400) * opacity_scale
        parts.append(
            f'<line x1="{_js_num(a["x"])}" y1="{_js_num(a["y"])}" x2="{_js_num(b["x"])}" y2="{_js_num(b["y"])}" '
            f'stroke="{color}" stroke-width="1" opacity="{opacity:.2f}">'
            f'<animate attributeName="x1" values="{_js_num(a["x"])};{_js_num(a["x"]+a["dx"])};{_js_num(a["x"])}" dur="{a["dur"]:.1f}s" repeatCount="indefinite"/>'
            f'<animate attributeName="y1" values="{_js_num(a["y"])};{_js_num(a["y"]+a["dy"])};{_js_num(a["y"])}" dur="{a["dur"]*1.2:.1f}s" repeatCount="indefinite"/>'
            f'<animate attributeName="x2" values="{_js_num(b["x"])};{_js_num(b["x"]+b["dx"])};{_js_num(b["x"])}" dur="{b["dur"]:.1f}s" repeatCount="indefinite"/>'
            f'<animate attributeName="y2" values="{_js_num(b["y"])};{_js_num(b["y"]+b["dy"])};{_js_num(b["y"])}" dur="{b["dur"]*1.2:.1f}s" repeatCount="indefinite"/>'
            f'</line>'
        )
    for p in pts:
        opacity_attr = f' opacity="{opacity_scale:.2f}"' if opacity_scale != 1.0 else ""
        pulse_anim = (
            f'<animate attributeName="r" values="{p["r"]:.1f};{p["r"]*1.8:.1f};{p["r"]:.1f}" dur="{rnd.uniform(2,4):.1f}s" repeatCount="indefinite"/>'
            if pulse else ""
        )
        parts.append(
            f'<circle cx="{_js_num(p["x"])}" cy="{_js_num(p["y"])}" r="{p["r"]:.1f}" fill="{color}"{opacity_attr}>'
            f'<animate attributeName="cx" values="{_js_num(p["x"])};{_js_num(p["x"]+p["dx"])};{_js_num(p["x"])}" dur="{p["dur"]:.1f}s" repeatCount="indefinite"/>'
            f'<animate attributeName="cy" values="{_js_num(p["y"])};{_js_num(p["y"]+p["dy"])};{_js_num(p["y"])}" dur="{p["dur"]*1.2:.1f}s" repeatCount="indefinite"/>'
            f'{pulse_anim}'
            f'</circle>'
        )
    return "".join(parts)



BANNER_FONT_SIZE = 40
BANNER_FONT_ALIGN_Y = 50  # % da altura, de cima pra baixo -- centralizado


def build_banner_svg(name="Gustavo Vieira de Araújo"):
    """Banner com o nome escrito normal (texto de verdade, legivel) sobre
    uma rede de particulas abstrata (nao tenta desenhar o nome, so
    decoracao de fundo), distribuida em grade com jitter pra cobrir a
    faixa toda de forma uniforme, sem aglomerar num canto. Os pontos
    desviam de uma caixa estimada em volta do texto (text_box), entao a
    rede preenche o espaco livre ao redor do nome em vez de passar por
    baixo dele. Tema escuro pra bater com os cartoes de estatistica. O
    fade-in do texto usa CSS @keyframes (roda normalmente dentro de <img>
    no GitHub); os pontos da rede animam via SMIL (tambem confirmado
    rodando ao vivo). Ajuste BANNER_PARTICLE_* no topo do arquivo pra
    mudar quantidade de pontos, alcance de movimento, cor etc."""
    width, height = BANNER_WIDTH, BANNER_HEIGHT
    text_w = len(name) * BANNER_FONT_SIZE * 0.56
    text_h = BANNER_FONT_SIZE * 1.3
    pad = 14
    text_box = (
        width / 2 - text_w / 2 - pad, height * BANNER_FONT_ALIGN_Y / 100 - text_h / 2 - pad,
        width / 2 + text_w / 2 + pad, height * BANNER_FONT_ALIGN_Y / 100 + text_h / 2 + pad,
    )
    particles = _particle_network_content(
        width, height, BANNER_PARTICLE_COUNT, BANNER_PARTICLE_SEED,
        BANNER_PARTICLE_LINK_DIST, BANNER_PARTICLE_COLOR, BANNER_PARTICLE_MOVE_RANGE, BANNER_PARTICLE_DUR_RANGE,
        exclude_box=text_box,
    )
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" '
        f'viewBox="0 0 {width} {height}" role="img" aria-label="{name}">'
        '<style>'
        f'.text {{ font-size: {BANNER_FONT_SIZE}px; font-weight: 700; '
        'font-family: -apple-system,BlinkMacSystemFont,Segoe UI,Helvetica,Arial,sans-serif,Apple Color Emoji,Segoe UI Emoji; '
        'animation: fadeIn 1.2s ease-in-out forwards; }'
        '@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }'
        '</style>'
        f'<rect width="{width}" height="{height}" fill="{BANNER_BG}"/>'
        f'{particles}'
        f'<text text-anchor="middle" dominant-baseline="middle" x="50%" y="{BANNER_FONT_ALIGN_Y}%" '
        f'class="text" fill="#{BANNER_FONT_COLOR}">{name}</text>'
        '</svg>'
    )


def build_divider_svg():
    """Linha divisoria fina, mesmo tom do fundo do banner/cartoes."""
    width, height = BANNER_WIDTH, 4
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" '
        f'viewBox="0 0 {width} {height}">'
        f'<rect width="{width}" height="{height}" fill="{CARD_STROKE}"/></svg>'
    )


