BADGES_DIR = os.path.join(DOCS_DIR, "badges")
BADGES_BASE_URL = "https://raw.githubusercontent.com/GustavoVieiraDeAraujo/Orion-Index/main/docs/badges"

BADGE_H = 28
BADGE_FONT_SIZE = 11
BADGE_ICON_SIZE = 14
BADGE_PAD_X = 9
BADGE_ICON_GAP = 6


def _badge_text_width(text):
    """Estimativa de largura de texto maiusculo em negrito -- nao tem
    biblioteca de metrica de fonte disponivel, entao aproxima por
    caractere. 0.72 foi medido de verdade (Playwright + getBBox) com a
    fonte que realmente renderiza aqui -- Verdana nao costuma estar
    instalada (nem aqui nem na maioria dos sistemas), cai pra um
    substituto mais largo, e um fator menor tipo 0.62 deixava nome comprido
    tipo 'POSTGRESQL' vazando pra fora do badge."""
    return len(text) * BADGE_FONT_SIZE * 0.72


def render_badge_svg(label, hex_color, icon_d, icon_color):
    """Desenha um badge no estilo shields.io 'for-the-badge' (retangulo
    solido, icone + texto maiusculo), mas como SVG proprio: nada disso
    chama servico externo pra renderizar."""
    text = label.upper()
    has_icon = bool(icon_d)
    icon_w = BADGE_ICON_SIZE + BADGE_ICON_GAP if has_icon else 0
    width = round(BADGE_PAD_X * 2 + icon_w + _badge_text_width(text))

    icon_svg = ""
    if has_icon:
        scale = BADGE_ICON_SIZE / 24
        icon_y = (BADGE_H - BADGE_ICON_SIZE) / 2
        icon_svg = (
            f'<g transform="translate({BADGE_PAD_X},{icon_y:.1f}) scale({scale:.4f})">'
            f'<path d="{icon_d}" fill="{icon_color}"/></g>'
        )
    text_x = BADGE_PAD_X + icon_w

    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{BADGE_H}" '
        f'viewBox="0 0 {width} {BADGE_H}" role="img" aria-label="{text}">'
        f'<rect width="{width}" height="{BADGE_H}" fill="#{hex_color}"/>'
        f'{icon_svg}'
        f'<text x="{text_x}" y="{BADGE_H / 2:.0f}" fill="{icon_color}" '
        f'font-family="Verdana, Geneva, sans-serif" font-size="{BADGE_FONT_SIZE}" '
        f'font-weight="bold" letter-spacing="0.5" dominant-baseline="central">{text}</text>'
        f'</svg>'
    )


def build_skills_block(topics_count, total_lines):
    """Ordena por linguagens medidas em LOC primeiro (dado mais confiavel),
    depois ferramentas/frameworks que so os topicos revelam (React, Rails,
    Postgres etc). Cada badge vira um SVG proprio em docs/badges/, servido
    depois via raw.githubusercontent.com -- sem chamada ao shields.io."""
    codes = []

    lang_ranked = sorted(total_lines.items(), key=lambda kv: kv[1], reverse=True)
    for lang, _ in lang_ranked:
        code = LANG_TO_SKILLICON.get(lang)
        if code and code not in codes:
            codes.append(code)

    topic_ranked = sorted(topics_count.items(), key=lambda kv: (-kv[1], kv[0]))
    for topic, _ in topic_ranked:
        code = TOPIC_TO_SKILLICON.get(topic)
        if code and code not in codes:
            codes.append(code)

    if not codes:
        return "_nenhuma tecnologia catalogada ainda_"
    codes = codes[:14]

    os.makedirs(BADGES_DIR, exist_ok=True)
    badges = []
    for code in codes:
        info = BADGE_INFO.get(code)
        if not info:
            continue
        label, color, logo, logo_color, url = info
        alt = label.replace("%20", " ").replace("--", "-").replace("%23", "#")
        svg = render_badge_svg(alt, color, ICON_PATHS.get(logo), logo_color)
        with open(os.path.join(BADGES_DIR, f"{code}.svg"), "w", encoding="utf-8") as f:
            f.write(svg)
        badge_url = f"{BADGES_BASE_URL}/{code}.svg"
        badges.append(f'<a href="{url}" target="_blank"><img src="{badge_url}" alt="{alt}" height="30" /></a>')
    return " ".join(badges)


def perguntar_gemini(prompt, api_key):
    """Mesmo endpoint/formato usado em kalymos-cartwheel
    (src/assistente/gemini.ts): POST direto na API do Gemini, sem SDK."""
    body = json.dumps({"contents": [{"parts": [{"text": prompt}]}]}).encode("utf-8")
    req = urllib.request.Request(
        f"{GEMINI_URL}?key={api_key}",
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            data = json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"Gemini respondeu {e.code}: {e.read().decode()[:300]}")
    texto = data.get("candidates", [{}])[0].get("content", {}).get("parts", [{}])[0].get("text")
    if not texto:
        raise RuntimeError("Gemini nao retornou texto na resposta")
    return texto.strip()


ANALISE_INSTRUCAO_COMUM = (
    'Escreva um paragrafo curto (4 a 6 frases) em portugues do Brasil, tom natural e tecnico '
    '(nem robotico nem vendedor). Baseie-se SOMENTE nos numeros fornecidos acima, nao invente '
    'nenhum numero, fonte externa ou fato que nao esteja nos dados. Nao use markdown nenhum '
    '(sem #, sem **negrito**, sem o caractere travessao "—", sem listas), so texto corrido em '
    'paragrafo unico. Nao comece com saudacao nem introducao tipo "Analisando os dados...", '
    'va direto ao ponto.'
)


def format_analysis_block(title, body, generated):
    """Titulo + corpo, e um rodape pequeno dizendo qual ferramenta gerou o
    texto (so quando `generated=True`, ja que um texto de aviso/erro nao foi
    gerado por nada)."""
    footer = (
        "\n\n<sub>Gerado automaticamente pela [API do Gemini](https://ai.google.dev/) (Google), "
        "com base nos dados acima.</sub>"
        if generated else ""
    )
    return f"**{title}**\n\n{body}{footer}"


def build_world_analysis_text(api_key):
    """Le o JSON de dados crus gerado por generate.py (scripts/generate.py,
    mesmo repositorio) e pede pro Gemini justificar os numeros com o
    contexto atual do mercado de tecnologia -- nao inventa numero novo, so
    comenta em cima do que ja foi buscado ao vivo na API do GitHub."""
    titulo = "🧠 Leitura da IA"
    if not api_key:
        return format_analysis_block(titulo, "_analise indisponivel: GEMINI_API_KEY nao configurada_", False)
    if not os.path.exists(ORION_INDEX_DATA_JSON):
        return format_analysis_block(titulo, "_dados do Orion Index ainda nao disponiveis para analise_", False)
    with open(ORION_INDEX_DATA_JSON, "r", encoding="utf-8") as f:
        dados = json.load(f)

    prompt = f'''Estes sao dados reais e ao vivo da API do GitHub sobre linguagens de programacao, coletados hoje ({dados["gerado_em"]}):

Repositorios criados nos ultimos 30 dias, por linguagem (top 5): {dados["repositorios_novos"]["top5"]}
Repositorios publicos totais existentes, por linguagem (top 5): {dados["repositorios_totais"]["top5"]}
Repositorios por topico de finalidade, ex: IA, APIs, automacao (top 5): {dados["repositorios_por_finalidade"]["top5"]}
Crescimento relativo (novos / totais, em %), por linguagem (top 5): {dados["crescimento_relativo"]["top5"]}

{ANALISE_INSTRUCAO_COMUM} Tente explicar/justificar esses numeros especificos usando o contexto atual do mercado de tecnologia e da industria de software (ex: adocao de IA, tendencias de linguagem, tipo de projeto que cada uma favorece).'''

    try:
        return format_analysis_block(titulo, perguntar_gemini(prompt, api_key), True)
    except (RuntimeError, urllib.error.URLError) as e:
        print(f"[aviso] falha ao gerar analise de mercado: {e}", file=sys.stderr)
        return format_analysis_block(titulo, "_falha ao gerar analise nesta execucao_", False)


def build_profile_analysis_text(repo_total_lines, total_lines, repo_commits,
                                 topics_count, year_count, grand_total, api_key):
    """Usa so os dados computados dos proprios repositorios (linguagem por
    LOC, commits, topicos, anos) -- sem contexto pessoal manual, por decisao
    explicita: fica sempre atualizado sozinho, sem precisar editar o script
    quando algo pessoal mudar (curso, estagio etc)."""
    titulo = "🧠 Leitura da IA"
    if not api_key:
        return format_analysis_block(titulo, "_analise indisponivel: GEMINI_API_KEY nao configurada_", False)

    top_langs = sorted(total_lines.items(), key=lambda kv: kv[1], reverse=True)[:6]
    top_repos = sorted(repo_total_lines.items(), key=lambda kv: kv[1], reverse=True)[:5]
    top_commits = sorted(repo_commits.items(), key=lambda kv: kv[1], reverse=True)[:5]
    top_topics = sorted(topics_count.items(), key=lambda kv: kv[1], reverse=True)[:8]

    prompt = f'''Estes sao dados reais extraidos hoje dos repositorios publicos no GitHub de uma pessoa desenvolvedora:

Linhas de codigo por linguagem, todos os repositorios somados (top 6): {top_langs}
Total de linhas de codigo analisadas: {grand_total}
Repositorios com mais linhas de codigo (top 5): {top_repos}
Repositorios com mais commits (top 5): {top_commits}
Topicos/areas mais recorrentes nos repositorios (top 8): {top_topics}
Repositorios criados por ano: {dict(sorted(year_count.items()))}

{ANALISE_INSTRUCAO_COMUM} Escreva em segunda pessoa (falando diretamente com essa pessoa, "voce"), analisando o que esses dados revelam sobre o perfil dela como desenvolvedora: pontos fortes aparentes, area de foco, e trajetoria olhando a evolucao por ano. Nao invente nada sobre formacao, emprego ou biografia que nao esteja nos dados acima.'''

    try:
        return format_analysis_block(titulo, perguntar_gemini(prompt, api_key), True)
    except (RuntimeError, urllib.error.URLError) as e:
        print(f"[aviso] falha ao gerar analise de perfil: {e}", file=sys.stderr)
        return format_analysis_block(titulo, "_falha ao gerar analise nesta execucao_", False)


def push_profile_readme(blocks, pat):
    """Clona o repo de perfil com o PAT embutido na URL, substitui os blocos
    marcados no README.md e da commit+push."""
    tmp = tempfile.mkdtemp(prefix="profile-")
    url = f"https://x-access-token:{pat}@github.com/{PROFILE_REPO_FULL}.git"
    try:
        subprocess.run(["git", "clone", "--depth", "1", "--quiet", url, tmp], check=True, capture_output=True, text=True)

        readme_path = os.path.join(tmp, "README.md")
        with open(readme_path, "r", encoding="utf-8") as f:
            content = f.read()

        for key, (start, end) in MARKERS.items():
            pattern = re.compile(re.escape(start) + r".*?" + re.escape(end), re.DOTALL)
            if not pattern.search(content):
                print(f"Marcadores {key} nao encontrados no README do perfil", file=sys.stderr)
                sys.exit(1)
            content = pattern.sub(f"{start}\n{blocks[key]}\n{end}", content)

        with open(readme_path, "w", encoding="utf-8") as f:
            f.write(content)

        subprocess.run(["git", "-C", tmp, "config", "user.name", "github-actions[bot]"], check=True)
        subprocess.run(["git", "-C", tmp, "config", "user.email",
                         "41898282+github-actions[bot]@users.noreply.github.com"], check=True)

        diff = subprocess.run(["git", "-C", tmp, "diff", "--quiet"], capture_output=True)
        if diff.returncode == 0:
            print("Perfil: sem mudancas no README.")
            return

        subprocess.run(["git", "-C", tmp, "add", "README.md"], check=True)
        subprocess.run(["git", "-C", tmp, "commit", "-m", "Update README.md"], check=True)
        subprocess.run(["git", "-C", tmp, "push"], check=True, capture_output=True, text=True)
        print("Perfil: README.md atualizado e enviado.")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def main():
    pat = os.environ.get("PROFILE_PAT")
    if not pat:
        print("PROFILE_PAT nao configurado (precisa de permissao de escrita no repositorio de perfil)", file=sys.stderr)
        sys.exit(1)

    gemini_key = os.environ.get("GEMINI_API_KEY")
    if not gemini_key:
        print("[aviso] GEMINI_API_KEY nao configurada: blocos de analise ficam com texto de aviso", file=sys.stderr)

    repos = list_profile_repos()
    print(f"Repositorios do perfil encontrados: {len(repos)}")

    total_lines = {}
    repo_total_lines = {}
    repo_commits = {}
    topics_count = {}
    year_count = {}

    for repo in repos:
        print(f"- {repo['name']}")
        for topic in repo.get("topics") or []:
            if topic in TOPIC_BLOCKLIST:
                continue
            topics_count[topic] = topics_count.get(topic, 0) + 1

        year = repo["created_at"][:4]
        year_count[year] = year_count.get(year, 0) + 1

        counts = count_lines(repo["full_name"])
        repo_total = sum(counts.values())
        if repo_total:
            repo_total_lines[repo["name"]] = repo_total
        for lang, n in counts.items():
            total_lines[lang] = total_lines.get(lang, 0) + n

        n_commits = count_commits(repo["full_name"])
        if n_commits:
            repo_commits[repo["name"]] = n_commits

    grand_total = sum(total_lines.values())
    # cronologico (nao por contagem): conta o crescimento do portfolio ao
    # longo do tempo, nao "ano com mais repos primeiro"
    year_count = dict(sorted(year_count.items()))

    # ordem bate com a ordem dos bullets no NOTE do README (texto mais
    # curto primeiro, mais longo por ultimo) -- linha 1: Mais Extensos +
    # Linguagens, linha 2: Por Ano + Por Commits
    row1_paths = []
    p = os.path.join(DOCS_DIR, "profile_biggest_repos.svg")
    render_bar_card(repo_total_lines, "Repositórios Mais Extensos", p,
                     unit="loc", default_color="#38bdf8", grad_id="gradBiggest",
                     layout="stacked", label_chars=40)
    row1_paths.append(p)

    p = os.path.join(DOCS_DIR, "profile_lang_loc.svg")
    render_bar_card(total_lines, "Linguagens por Linhas", p,
                     unit="pct", color_map=LANG_COLORS, grad_id="gradLangLoc",
                     layout="stacked", label_chars=40)
    row1_paths.append(p)

    p = os.path.join(DOCS_DIR, "profile_by_year.svg")
    render_bar_card(year_count, "Repositórios por Ano", p,
                     unit="count", default_color="#a78bfa", grad_id="gradByYear",
                     layout="stacked", label_chars=40, order="key", top_n=10)
    row1_paths.append(p)

    p = os.path.join(DOCS_DIR, "profile_commits.svg")
    render_bar_card(repo_commits, "Repositórios por Commits", p,
                     unit="count", default_color="#f59e0b", grad_id="gradCommits",
                     layout="stacked", label_chars=40)
    row1_paths.append(p)

    build_combined_row(row1_paths, os.path.join(DOCS_DIR, "profile_row1.svg"))

    with open(os.path.join(DOCS_DIR, "profile_banner.svg"), "w", encoding="utf-8") as f:
        f.write(build_banner_svg())
    with open(os.path.join(DOCS_DIR, "profile_divider.svg"), "w", encoding="utf-8") as f:
        f.write(build_divider_svg())

    blocks = {
        "STATS_MEU_REPO_CARTAO": build_mine_img_block(),
        "STATS_MUNDO_CARTAO": build_world_img_block(),
        "SKILLS": build_skills_block(topics_count, total_lines),
        "ANALISE_MEU_REPO": build_profile_analysis_text(
            repo_total_lines, total_lines, repo_commits, topics_count, year_count, grand_total, gemini_key,
        ),
        "ANALISE_MUNDO": build_world_analysis_text(gemini_key),
    }

    push_profile_readme(blocks, pat)
    print("Cartoes gerados em docs/profile_*.svg.")


if __name__ == "__main__":
    main()
